package dev.raf.radar;
import android.app.*;import android.content.*;import android.location.LocationManager;import android.net.*;import android.os.*;
import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import org.json.*;
final class Diagnostics {
 static Context app;static DiagnosticJournal journal;static final ScheduledExecutorService worker=Executors.newSingleThreadScheduledExecutor();static long retryAt;static int failures;static volatile boolean foreground;static volatile long heartbeat;static final Map<String,Long> recent=new ConcurrentHashMap<>();
 interface Upload{int send(String body,String token)throws Exception;}static Upload transport=Diagnostics::upload;
 static synchronized void init(Context c){if(app!=null)return;app=c.getApplicationContext();journal=new DiagnosticJournal(new File(app.getFilesDir(),"diagnostics"),System::currentTimeMillis);heartbeat=SystemClock.elapsedRealtime();
  final Thread.UncaughtExceptionHandler previous=Thread.getDefaultUncaughtExceptionHandler();Thread.setDefaultUncaughtExceptionHandler((thread,error)->{try{journal.event("app","uncaught","fatal",error,0,-1,-1,null);journal.report("uncaught",device(),snapshot(),true);}catch(Throwable ignored){}finally{if(previous!=null)previous.uncaughtException(thread,error);else{android.os.Process.killProcess(android.os.Process.myPid());System.exit(10);}}});
  Handler main=new Handler(Looper.getMainLooper());main.post(new Runnable(){public void run(){heartbeat=SystemClock.elapsedRealtime();main.postDelayed(this,10000);}});
  worker.scheduleWithFixedDelay(()->{try{check();journal.maintain();journal.report("error_window",device(),snapshot(),false);flush();}catch(Exception ignored){}},15,60,TimeUnit.SECONDS);
  info("app","launch");previousExit();
 }
 static void previousExit(){if(Build.VERSION.SDK_INT<30)return;try{for(ApplicationExitInfo exit:app.getSystemService(ActivityManager.class).getHistoricalProcessExitReasons(app.getPackageName(),0,1)){long seen=app.getSharedPreferences("radar",0).getLong("diagExitSeen",0);if(exit.getTimestamp()<=seen)continue;app.getSharedPreferences("radar",0).edit().putLong("diagExitSeen",exit.getTimestamp()).apply();int reason=exit.getReason();if(reason==ApplicationExitInfo.REASON_ANR||reason==ApplicationExitInfo.REASON_CRASH||reason==ApplicationExitInfo.REASON_CRASH_NATIVE||reason==ApplicationExitInfo.REASON_LOW_MEMORY)error("app","previous_exit_"+reason,null,0,-1,-1,null);}}catch(Exception e){error("app","exit_info_unavailable",e,0,-1,-1,null);}}
 static void info(String area,String event){record(area,event,"info",null,0,-1,-1,null);}
 static void error(String area,String event,Throwable e,int http,long duration,long pause,String target){record(area,event,"error",e,http,duration,pause,target);}
 static void record(String area,String event,String level,Throwable e,int http,long duration,long pause,String target){if(journal==null)return;worker.execute(()->{try{journal.event(area,event,level,e,http,duration,pause,target);if(!"info".equals(level)){app.getSharedPreferences("radar",0).edit().putString("diagLastError",DiagnosticJournal.word(area)+"/"+DiagnosticJournal.word(event)+(http>0?" HTTP "+http:"")+(e==null?"":" "+DiagnosticJournal.word(e.getClass().getSimpleName()))).apply();journal.report(event,device(),snapshot(),false);flush();}}catch(Exception ignored){}});}
 static void once(String area,String event,boolean error){long now=SystemClock.elapsedRealtime();String key=area+":"+event;Long before=recent.putIfAbsent(key,now);if(before!=null&&now-before<60000)return;recent.put(key,now);record(area,event,error?"error":"info",null,0,-1,-1,null);}
 static void check(){if(app==null)return;android.content.SharedPreferences p=app.getSharedPreferences("radar",0);long now=System.currentTimeMillis();boolean expected=p.getBoolean("diagMonitorExpected",false);if(expected){if(!MonitorService.running)once("monitor","service_inactive",true);else{long tick=p.getLong("diagTickAt",now);if(now-tick>90000)once("monitor","scheduler_stalled",true);long baseline=Math.max(p.getLong("diagMonitorSince",now),p.getLong("diagSuccessAt",0));long threshold=Math.max(300000,p.getInt("interval",120)*2000L+60000);if(now-baseline>threshold)once("taxi","no_successful_surcharge",true);if(!LocationState.fresh(new Store(app)))once("gps","no_fresh_fix",true);}}
  if(foreground&&app.getSystemService(PowerManager.class).isInteractive()&&SystemClock.elapsedRealtime()-heartbeat>30000)once("app","main_thread_stalled",true);
 }
 static JSONObject device(){JSONObject d=new JSONObject();try{d.put("version",BuildConfig.VERSION_NAME).put("versionCode",BuildConfig.VERSION_CODE).put("sdk",Build.VERSION.SDK_INT).put("manufacturer",Build.MANUFACTURER).put("model",Build.MODEL);}catch(JSONException ignored){}return d;}
 static JSONObject snapshot(){JSONObject s=new JSONObject();if(app==null)return s;try{android.content.SharedPreferences p=app.getSharedPreferences("radar",0);long now=System.currentTimeMillis();s.put("running",MonitorService.running).put("expected",p.getBoolean("diagMonitorExpected",false)).put("locationPermission",Access.location(app)).put("notifications",Access.notifications(app)).put("widget",p.getBoolean("overlay",false)).put("sharing",p.getBoolean("shareLocation",false));LocationManager lm=app.getSystemService(LocationManager.class);s.put("gpsEnabled",lm!=null&&lm.isLocationEnabled());ConnectivityManager cm=app.getSystemService(ConnectivityManager.class);NetworkCapabilities caps=cm==null?null:cm.getNetworkCapabilities(cm.getActiveNetwork());s.put("network",caps!=null&&caps.hasCapability(NetworkCapabilities.NET_CAPABILITY_INTERNET));
   String[] keys={"gpsAt","diagTickAt","diagAttemptAt","diagSuccessAt"},names={"gpsAgeSeconds","lastTickAgeSeconds","lastAttemptAgeSeconds","lastSuccessAgeSeconds"};for(int i=0;i<keys.length;i++)if(p.getLong(keys[i],0)>0)s.put(names[i],Math.min(Integer.MAX_VALUE,Math.max(0,(now-p.getLong(keys[i],now))/1000)));s.put("pauseRemainingSeconds",Math.max(0,(p.getLong("diagPauseUntil",0)-now+999)/1000));int enabled=0;for(Point point:new Store(app).points())if(point.enabled)enabled++;s.put("enabledPoints",enabled);File[] queue=journal.root.listFiles((d,n)->n.startsWith("report-"));s.put("queuePending",queue==null?0:queue.length);
  }catch(Exception ignored){}return s;}
 static void flush(){if(app==null||SystemClock.elapsedRealtime()<retryAt)return;File file=journal.pending();if(file==null)return;String token=AccountClient.session(new Store(app));if(token==null)return;
  try{int status=transport.send(DiagnosticJournal.read(file),token);app.getSharedPreferences("radar",0).edit().putInt("diagUploadHttp",status).apply();if(status==200){journal.acknowledged(file);failures=0;retryAt=SystemClock.elapsedRealtime()+60000;app.getSharedPreferences("radar",0).edit().putLong("diagUploadedAt",System.currentTimeMillis()).apply();}else if(status==400||status==413){journal.acknowledged(file);retryAt=SystemClock.elapsedRealtime()+900000;}else retry();}catch(Exception e){retry();}
 }
 static void retry(){failures=Math.min(6,failures+1);retryAt=SystemClock.elapsedRealtime()+Math.min(3600000,60000L*(1L<<failures));}
 static int upload(String body,String token)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://radar-presence.vercel.app/api/diagnostics").openConnection();try{c.setConnectTimeout(8000);c.setReadTimeout(20000);c.setRequestMethod("POST");c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");c.setRequestProperty("Authorization","Bearer "+token);try(OutputStream out=c.getOutputStream()){out.write(body.getBytes(StandardCharsets.UTF_8));}return c.getResponseCode();}finally{c.disconnect();}}
 static void ui(MainActivity a){check();new AlertDialog.Builder(a).setTitle("Диагностика").setMessage(summary()).setPositiveButton("Закрыть",null).setNeutralButton("Скопировать отчёт",(d,w)->((ClipboardManager)a.getSystemService(Context.CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("Радар · диагностика",summary()))).setNegativeButton("Отправить отчёт",(d,w)->{worker.execute(()->{journal.event("app","manual_report","error",null,0,-1,-1,null);journal.report("manual_report",device(),snapshot(),true);retryAt=0;flush();});a.toast("Отчёт поставлен в очередь отправки");}).show();}
 static String summary(){if(app==null)return "Диагностика не запущена";android.content.SharedPreferences p=app.getSharedPreferences("radar",0);return "Радар "+BuildConfig.VERSION_NAME+"\nID: "+p.getInt("accountId",0)+"\n"+snapshot().toString()+"\nПоследняя ошибка: "+p.getString("diagLastError","нет")+"\nПоследняя отправка: "+(p.getLong("diagUploadedAt",0)==0?"ещё не было":new java.text.SimpleDateFormat("dd.MM HH:mm:ss",java.util.Locale.getDefault()).format(new java.util.Date(p.getLong("diagUploadedAt",0))))+"\nHTTP отправки: "+p.getInt("diagUploadHttp",0);}
}
